  "114:4": { surah: 114, ayah: 4, page: 604, words: [{"code":"ﱻ","text":"مِن"},{"code":"ﱼ","text":"شَرِّ"},{"code":"ﱽ","text":"ٱلۡوَسۡوَاسِ"},{"code":"ﱾ","text":"ٱلۡخَنَّاسِ"}], endMarker: "ﱿ" },
  "114:5": { surah: 114, ayah: 5, page: 604, words: [{"code":"ﲀ","text":"ٱلَّذِي"},{"code":"ﲁ","text":"يُوَسۡوِسُ"},{"code":"ﲂ","text":"فِي"},{"code":"ﲃ","text":"صُدُورِ"},{"code":"ﲄ","text":"ٱلنَّاسِ"}], endMarker: "ﲅ" },
