export function getTajweedAyah(verseKey: string): TajweedAyahData | null {
  return TAJWEED_GLYPHS[verseKey] ?? null;
}

export function fontFamilyForPage(page: number): string | null {
  if (page < 1 || page > 604) return null;
  return `QPC4Tajweed-${String(page).padStart(3, '0')}`;
}

export const ALL_TAJWEED_FONT_FAMILIES: string[] = Array.from({ length: 604 }, (_, i) => `QPC4Tajweed-${String(i + 1).padStart(3, '0')}`);
